import json
from pathlib import Path

OUT = Path(__file__).parent / "test-cases"
OUT.mkdir(parents=True, exist_ok=True)


def request(method, path, body=None, query=None, auth=True, headers=None):
    merged_headers = {}
    if auth:
        merged_headers["Authorization"] = "Bearer {{global.accessToken}}"
    if headers:
        merged_headers.update(headers)
    return {
        "method": method,
        "path": path,
        "headers": merged_headers,
        "query": query or {},
        "body": body or {},
    }


def case(case_id, title, description, severity, precondition, request_message, status, checks, db=None):
    return {
        "caseId": case_id,
        "title": title,
        "description": description,
        "severity": severity,
        "precondition": precondition,
        "requestMessage": request_message,
        "expectedResponse": {"statusCode": status, "checks": checks},
        "dbExpectation": db or [],
    }


def write(filename, module, cases):
    payload = {"module": module, "basePath": "/api/v1", "testCases": cases}
    (OUT / filename).write_text(json.dumps(payload, indent=2), encoding="utf-8")


