def simple_master_cases(prefix, module, base_path, name_field, duplicate_value, body, update_body, missing_id_var):
    lower = module.lower()
    return [
        case(f"{prefix}-API-001", f"List {lower} succeeds", f"Verify {lower} can be listed.", "High", AUTH, request("GET", base_path), 200, ["Response contains items array."]),
        case(f"{prefix}-API-002", f"List {lower} filters active flag", f"Verify {lower} list can filter by active status.", "Medium", AUTH, request("GET", base_path, query={"isActive": "true"}), 200, ["Every returned record has isActive true."]),
        case(f"{prefix}-API-003", f"Search {lower} succeeds", f"Verify search filters {lower}.", "Medium", AUTH, request("GET", base_path, query={"search": duplicate_value.split()[0]}), 200, ["Returned records match search criteria when data exists."]),
        case(f"{prefix}-API-004", f"Create {lower} succeeds", f"Verify a {lower} record can be created.", "High", AUTH, request("POST", base_path, body), 201, ["Response contains id.", f"Response {name_field} matches request."], [f"{lower} record is created."]),
        case(f"{prefix}-API-005", f"Create {lower} rejects duplicate name", f"Verify duplicate {lower} name is rejected.", "High", AUTH, request("POST", base_path, {**body, name_field: duplicate_value}), 400, ["Response indicates name already exists."], [f"No {lower} record is created."]),
        case(f"{prefix}-API-006", f"Create {lower} rejects missing name", f"Verify {name_field} is mandatory.", "Medium", AUTH, request("POST", base_path, {k: v for k, v in body.items() if k != name_field}), 400, ["Response indicates validation error."]),
        case(f"{prefix}-API-007", f"Update {lower} succeeds", f"Verify {lower} can be updated.", "High", ["User is authenticated.", f"A disposable {lower} record exists."], request("PATCH", f"{base_path}/{{{{created{module[:-1]}Id}}}}", update_body), 200, [f"Response {name_field} or status matches request."], [f"{lower} record is updated."]),
        case(f"{prefix}-API-008", f"Update {lower} rejects duplicate name", f"Verify {lower} update prevents duplicate name.", "High", ["User is authenticated.", f"A disposable {lower} record exists."], request("PATCH", f"{base_path}/{{{{created{module[:-1]}Id}}}}", {name_field: duplicate_value}), 400, ["Response indicates name already exists."], [f"{lower} record remains unchanged."]),
        case(f"{prefix}-API-009", f"Update {lower} not found", f"Verify updating a missing {lower} returns not found.", "Medium", AUTH, request("PATCH", f"{base_path}/{{{{{missing_id_var}}}}}", update_body), 404, [f"Response indicates {lower} not found."]),
    ]


def projects_cases():
    return simple_master_cases("PROJECTS", "Projects", "/api/v1/projects", "projectName", "Billing Core", {"projectName": "API Project {{global.runId}}", "description": "Created by API test.", "isActive": True}, {"projectName": "API Project Updated {{global.runId}}", "description": "Updated by API test.", "isActive": False}, "missingProjectId")


def environments_cases():
    cases = simple_master_cases("ENV", "Environments", "/api/v1/environments", "environmentName", "UAT", {"environmentName": "QA-SANDBOX-{{global.runId}}", "description": "API test environment.", "isActive": True, "sortOrder": 20}, {"environmentName": "QA-SANDBOX-UPDATED-{{global.runId}}", "description": "Updated.", "isActive": False, "sortOrder": 21}, "missingEnvironmentId")
