def renumber(cases, prefix):
    for index, item in enumerate(cases, 1):
        item["caseId"] = f"{prefix}-API-{index:03d}"
    return cases


def main():
    setup_files()
    modules = [
        ("auth.testcases.json", "Auth", auth_cases()),
        ("users.testcases.json", "Users", users_cases()),
        ("projects.testcases.json", "Projects", projects_cases()),
        ("environments.testcases.json", "Environments", environments_cases()),
        ("releases.testcases.json", "Releases", releases_cases()),
        ("workflow.testcases.json", "Workflow", workflow_cases()),
        ("defects.testcases.json", "Defects", defects_cases()),
        ("attachments.testcases.json", "Attachments", attachments_cases()),
        ("inline-assets.testcases.json", "Inline Assets", inline_cases()),
        ("comments.testcases.json", "Comments", comments_cases()),
        ("history.testcases.json", "History", history_cases()),
        ("dashboard.testcases.json", "Dashboard", dashboard_cases()),
    ]
    for filename, module, cases in modules:
        write(filename, module, cases)
    summary = {}
    for path in sorted(OUT.glob("*.testcases.json")):
        data = json.loads(path.read_text(encoding="utf-8"))
        summary[path.name] = len(data["testCases"])
    print(json.dumps(summary, indent=2))
    print("TOTAL", sum(summary.values()))


if __name__ == "__main__":
    main()
